async function run() {
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode("abc"));
  console.log(Buffer.from(d).toString("hex"), d.byteLength);
  const s = await crypto.subtle.digest({ name: "SHA-1" }, new Uint8Array([97, 98, 99]));
  console.log(Buffer.from(s).toString("hex"));
}
function main(): void { run(); }
